SINA_SMART["biochem1-enzymes"] = {"lecture":"biochem1-enzymes","title":"Enzymes and coenzymes","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biochem1-enzymes:e0","text":"Enzymes: catalysts, proteins except ribozymes; lower activation energy.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e1","text":"Do not change yield or equilibrium; recycled; low doses.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e2","text":"Double specificity: substrate (lock and key) and reaction.","topic":"Specificity and naming","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e3","text":"Names end in -ase; EC number: 4 digits.","topic":"Specificity and naming","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e4","text":"Classes: oxidoreductases, transferases, hydrolases, lyases, isomerases, ligases.","topic":"Specificity and naming","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e5","text":"Regulation: allosteric, phosphorylation, association/dissociation.","topic":"Regulation and conditions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e6","text":"Inhibition: competitive, non-competitive, uncompetitive.","topic":"Regulation and conditions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e7","text":"Optimal pH and temperature.","topic":"Regulation and conditions","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e8","text":"Inorganic cofactors: Mg²⁺ (kinases), Zn²⁺, Fe²⁺, Se.","topic":"Cofactors and coenzymes","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-enzymes:e9","text":"Coenzymes: TPP, FAD, NAD⁺, biotin, CoA, PLP, CoQ, cytochrome c.","topic":"Cofactors and coenzymes","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"gnrkrq":"a","ukb7qd":"a","s27qah":"a","om4eul":"a","16j8ksd":"a","sxyhmd":"a","nb9sgf":"a","p8ha7p":"a","g9u6cv":"a","1bbvw31":"a","40xw4y":"a","4uhegx":"a","1m7q2yb":"a","1nj070q":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biochem1-enzymes:e0":{"s":0,"u":["Enzymes: catalysts, proteins except ribozymes; lower activation energy.","Enzymes are biological catalysts, proteins except the ribozymes (catalytic RNA).","They speed up reactions by lowering the activation energy , are recovered unchanged, act at low doses, and change neither the yield nor the equilibrium ."],"dp":[{"h":"Why enzymes don't change the equilibrium","t":"An enzyme lowers the energy barrier for the forward and reverse reactions equally, so both go faster and equilibrium is simply reached sooner. The final ratio of products to substrates is set by thermodynamics, not by the catalyst. Cells steer metabolism by coupling reactions and by controlling which enzymes are active. Source: the lecture's biochemical properties slide."}]},"biochem1-enzymes:e1":{"s":0,"u":["Do not change yield or equilibrium; recycled; low doses.","They speed up reactions by lowering the activation energy , are recovered unchanged, act at low doses, and change neither the yield nor the equilibrium ."],"dp":[]},"biochem1-enzymes:e2":{"s":1,"u":["Double specificity: substrate (lock and key) and reaction.","Double specificity : for the substrate ('lock and key' model) and for the reaction (degradation or synthesis)."],"dp":[]},"biochem1-enzymes:e3":{"s":1,"u":["Names end in -ase; EC number: 4 digits.","Common names usually indicate substrate and reaction and end in -ase (glucokinase, proteases, lactate dehydrogenase; exceptions: pepsin, trypsin).","The EC number (International Union of Biochemistry) has four digits: class , subclass, sub-subclass, specific enzyme."],"dp":[]},"biochem1-enzymes:e4":{"s":1,"u":["Classes: oxidoreductases, transferases, hydrolases, lyases, isomerases, ligases.","Six classes: 1 oxidoreductases, 2 transferases, 3 hydrolases, 4 lyases, 5 isomerases, 6 ligases ."],"dp":[]},"biochem1-enzymes:e5":{"s":2,"u":["Regulation: allosteric, phosphorylation, association/dissociation.","Enzymes are switched on or off by allosteric effectors (binding at a site other than the active site, with cooperativity ), phosphorylation/dephosphorylation , and association/dissociation of subunits."],"dp":[]},"biochem1-enzymes:e6":{"s":2,"u":["Inhibition: competitive, non-competitive, uncompetitive.","Inhibition : competitive (inhibitor competes with the substrate for the active site; overcome by more substrate), non-competitive (binds elsewhere, lowers activity whatever the substrate level), uncompetitive (binds only the enzyme-substrate complex). pH changes charges and shape, preventing substrate binding; each enzyme has an optimal pH ."],"dp":[]},"biochem1-enzymes:e7":{"s":2,"u":["Optimal pH and temperature.","Temperature affects structure; each has an optimal temperature , above which it denatures."],"dp":[]},"biochem1-enzymes:e8":{"s":3,"u":["Inorganic cofactors: Mg²⁺ (kinases), Zn²⁺, Fe²⁺, Se.","Inorganic : Mg²⁺ (kinases), Zn²⁺ (DNA polymerase, alcohol dehydrogenase), Fe²⁺ (catalase), Se (glutathione peroxidases).","Cofactors are 'helper molecules'."],"dp":[]},"biochem1-enzymes:e9":{"s":3,"u":["Coenzymes: TPP, FAD, NAD⁺, biotin, CoA, PLP, CoQ, cytochrome c.","Main coenzymes: TPP (thiamine, B1: decarboxylation), FMN/FAD (riboflavin, B2: redox, 2 H), NAD⁺/NADP⁺ (niacin, B3: redox, hydride), biotin (carboxylation), coenzyme A (pantothenate: acyl carrier), pyridoxal phosphate (B6: amino-group transfer), coenzyme Q and cytochrome c (electron transfer)."],"dp":[]}},"meta":{"gnrkrq":{"a":"recall","vg":"biochem1-enzymes:e0/recall/1"},"ukb7qd":{"a":"recall","vg":"biochem1-enzymes:e0/recall/2"},"s27qah":{"a":"recall","vg":"biochem1-enzymes:e2/recall/1"},"om4eul":{"a":"recall","vg":"biochem1-enzymes:e3/recall/1"},"16j8ksd":{"a":"recall","vg":"biochem1-enzymes:e3/recall/2"},"sxyhmd":{"a":"recall","vg":"biochem1-enzymes:e8/recall/1"},"nb9sgf":{"a":"recall","vg":"biochem1-enzymes:e6/recall/1"},"p8ha7p":{"a":"recall","vg":"biochem1-enzymes:e6/recall/1"},"g9u6cv":{"a":"recall","vg":"biochem1-enzymes:e8/recall/2"},"1bbvw31":{"a":"recall","vg":"biochem1-enzymes:e8/recall/2"},"40xw4y":{"a":"recall","vg":"biochem1-enzymes:e9/recall/1"},"4uhegx":{"a":"recall","vg":"biochem1-enzymes:e9/recall/2"},"1m7q2yb":{"a":"recall","vg":"biochem1-enzymes:e9/recall/3"},"1nj070q":{"a":"recall","vg":"biochem1-enzymes:e9/recall/4"}},"explRev":"506fcbc3f1d8"};
